import React, { useState } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import FormSection from '../../../components/ui/FormSection/FormSection';
import InputField from '../../../components/ui/InputField/InputField';
import Button from '../../../components/ui/Button/Button';
import styles from './CreateOngPage.module.css';
import api from '../../../api/api'; // Importa o cliente da API

const CreateOngPage = () => {
  // Lógica para gerir o estado de todos os campos do formulário
  const [formData, setFormData] = useState({
    fantasy_name: '',
    corporate_name: '',
    cnpj: '',
    contact_email: '',
    phone: '',
    responsible_name: '',
    responsible_email: '',
    responsible_password: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  // Lógica para enviar os dados para a API quando o formulário é submetido
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await api.post('/ongs', formData);
      alert(`ONG "${response.data.message}" criada com sucesso!`);
      // Limpa o formulário
      setFormData({
        fantasy_name: '', corporate_name: '', cnpj: '', contact_email: '', phone: '',
        responsible_name: '', responsible_email: '', responsible_password: '',
      });
    } catch (error) {
      console.error("Erro ao criar ONG:", error);
      alert("Ocorreu um erro ao criar a ONG. Verifique a consola.");
    }
  };

  return (
    <ContentWrapper title="Cadastro de Nova ONG">
      <p className={styles.subtitle}>Preencha os dados abaixo para registar uma nova organização.</p>
      <form onSubmit={handleSubmit}>
        <FormSection number="1" title="Informações da ONG">
          <div className={styles.fullWidth}>
            <InputField label="Nome fantasia da ONG" name="fantasy_name" value={formData.fantasy_name} onChange={handleChange} />
          </div>
          <div className={styles.fullWidth}>
            <InputField label="Razão Social" name="corporate_name" value={formData.corporate_name} onChange={handleChange} />
          </div>
          <InputField label="CNPJ" name="cnpj" placeholder="00.000.000/0000-00" value={formData.cnpj} onChange={handleChange} />
        </FormSection>

        <FormSection number="2" title="Contato">
          <InputField label="Email de Contato" name="contact_email" value={formData.contact_email} onChange={handleChange} />
          <InputField label="Telefone / WhatsApp" name="phone" placeholder="(00) 00000-0000" value={formData.phone} onChange={handleChange} />
        </FormSection>

        <FormSection number="4" title="Informações do Responsável Legal">
            <InputField label="Nome do Responsável" name="responsible_name" value={formData.responsible_name} onChange={handleChange} />
            <InputField label="Email do Responsável" name="responsible_email" value={formData.responsible_email} onChange={handleChange} />
            <InputField label="Senha Provisória do Responsável" name="responsible_password" type="password" value={formData.responsible_password} onChange={handleChange} />
        </FormSection>

        <div className={styles.submitButton}>
            <Button type="submit">Finalizar Cadastro da ONG</Button>
        </div>
      </form>
    </ContentWrapper>
  );
};

export default CreateOngPage;
